<script setup>
import { computed } from 'vue';
import { safeError, money } from './settlementFinance.js';
import SettlementReportEvidence from './SettlementReportEvidence.vue';
const props = defineProps({ evidence: Object });
const basis = computed(() => props.evidence?.financial_basis || {});
const references = computed(() => (basis.value.references || []).map(ref => ({ ...ref, ...ref.shares })));
const labels = { refund_no: '退款单号', refund_id: '退款关联', execution_id: '退款执行关联', plan_hash: '退款计划校验值', source_order_ids: '原订单关联', rule_version: '冻结规则版本', completed_at: '退款完成时间' };
const basisLabels = { reference_settlement_id: '最终基线清算关联', baseline_hash: '最终基线校验值', segment_id: '经济段', window_hash: '经济窗口校验值', segment_context_hash: '经济段上下文校验值', exception_id: '成本例外关联', buyer_cash_amount: '买方实际现金退款', gross_amount: '财务收入冲回（含补差对应部分）', cost_amount: '成本冲回', profit_amount: '利润冲回', external_funding_return: '原补差付款方返还权益（非买方现金）', absorption_reversal: '平台吸收冲回（非买方现金）', original_amount: '经济段原金额', cumulative_refund_amount: '累计退款金额' };
const shareLabels = { platform_fee: '平台利润冲回', provider_share: '提供方利润冲回', service_share: '服务方利润冲回', expert_fee: '专家利润冲回', channel_fee: '渠道利润冲回' };
function value(key, v) { return Array.isArray(v) ? v.join('、') : ['buyer_cash_amount', 'external_funding_return', 'absorption_reversal', 'gross_amount', 'cost_amount', 'profit_amount', 'original_amount', 'cumulative_refund_amount'].includes(key) ? money(v) : v; }
</script>
<template><section v-if="evidence" class="refund-evidence" aria-label="退款清算追溯证据"><h3>退款清算追溯证据</h3><dl><template v-for="(label, key) in labels" :key="key"><dt>{{ label }}</dt><dd>{{ value(key, evidence[key]) || '—' }}</dd></template><dt>最终基线状态</dt><dd>{{ ({ ready: '已就绪', waiting: '待确认', unsupported: '证据不足，待人工复核' })[basis.status] || basis.status || '未知' }}</dd><template v-if="basis.reason"><dt>待处理原因</dt><dd>{{ safeError({ response: { data: { detail: basis.reason } } }) }}</dd></template><template v-for="(label, key) in basisLabels" :key="key"><template v-if="basis[key] != null"><dt>{{ label }}</dt><dd>{{ value(key, basis[key]) }}</dd></template></template><template v-for="(label, key) in shareLabels" :key="key"><template v-if="basis.shares?.[key] != null"><dt>{{ label }}</dt><dd>{{ money(basis.shares[key]) }}</dd></template></template></dl><section v-for="(ref, i) in references" :key="ref.segment_id || i"><h4>来源 {{ i + 1 }} · {{ ref.source_order_no || ref.source_order_id }}</h4><SettlementReportEvidence :row="ref" /></section></section></template>
<style scoped>.refund-evidence{min-width:0;font-size:12px;border-top:1px solid #e5e6eb;padding:16px 0}.refund-evidence h3{font-size:14px;margin:0 0 12px}.refund-evidence dl{display:grid;grid-template-columns:160px minmax(0,1fr);gap:10px}.refund-evidence dt{color:#697586}.refund-evidence dd{margin:0;overflow-wrap:anywhere;white-space:pre-wrap}@media(max-width:600px){.refund-evidence dl{grid-template-columns:1fr;gap:6px}.refund-evidence dd{margin-bottom:8px}}</style>
